        const todayEnd = new Date(todayStart);
        todayEnd.setUTCDate(todayEnd.getUTCDate() + 1);
        const todayEndTime = todayEnd.getTime();
    
        // FIX: Explicitly type allEvents to aid TypeScript's inference.
